<template>
  <div class="evidence-shell">
    <v-alert v-if="graph.truncated" type="warning" variant="tonal" density="compact">Graph traversal reached its safety cap.</v-alert>
    <div class="graph-toolbar"><div>{{ breadcrumb }}</div><div class="zoom"><button aria-label="Zoom out" @click="changeZoom(-.1)">−</button><button @click="zoom=1">{{ Math.round(zoom*100) }}%</button><button aria-label="Zoom in" @click="changeZoom(.1)">+</button></div></div>
    <div class="graph-canvas" :style="{zoom}" role="img" :aria-label="`Directed dependency graph with ${graph.resources.length} resources and ${graph.relations.length} relationships`">
      <div class="lanes"><span>GARDENER</span><span>IRONCORE API</span><span>ZONE PROVIDERS</span><span>PHYSICAL</span></div>
      <svg class="connectors" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true">
        <line v-for="(relation,index) in visibleRelations" :key="relation.from+relation.to" data-edge :x1="line(index).x1" :y1="line(index).y1" :x2="line(index).x2" :y2="line(index).y2"/>
      </svg>
      <button v-for="(resource,index) in visibleResources" :key="resource.key" class="graph-node" :class="nodeClass(resource,index)" @click="selectResource(resource.key)"><span>{{ label(resource.provenance.kind) }}</span><strong>{{ resource.provenance.name }}</strong><small>{{ detail(resource) }}</small><em>{{ evidenceFor(resource.key) }}</em></button>
      <aside v-if="selectedRelation" class="evidence-popover"><h3>Why this relationship?</h3><span>{{ selectedRelation.type }}</span><code>{{ selectedRelation.fieldPath||'observed resource relationship' }}</code><p>Confidence: {{ selectedRelation.confidence }} by {{ selectedRelation.evidence }}</p></aside>
    </div>
    <details class="fallback"><summary>Accessible relationship table</summary><TopologyRelations :graph="graph" :root-key="rootKey"/></details>
  </div>
</template>
<script setup lang="ts">
import { computed,ref } from 'vue'
import type { SreGraph,SreResource } from '@/api/sre'
import TopologyRelations from './TopologyRelations.vue'
const props=defineProps<{graph:SreGraph;rootKey:string}>(),selected=ref<string|null>(null)
const zoom=ref(1)
const visibleResources=computed(()=>props.graph.resources.slice(0,8)),visibleRelations=computed(()=>props.graph.relations.slice(0,8))
const selectedRelation=computed(()=>props.graph.relations.find(r=>r.from===selected.value||r.to===selected.value)||props.graph.relations[0])
const breadcrumb=computed(()=>{const root=props.graph.resources[0];return root?`${root.provenance.environment||'WDF4'}  ›  ${root.provenance.namespace||root.provenance.kind}  ›  ${root.provenance.name}`:'WDF4 dependency path'})
function selectResource(key:string){selected.value=key}
function changeZoom(delta:number){zoom.value=Math.max(.7,Math.min(1.3,Number((zoom.value+delta).toFixed(1))))}
function label(kind:string){return kind.replace(/([a-z])([A-Z])/g,'$1 $2').toUpperCase()}
function detail(resource:SreResource){if(resource.state)return resource.state;if(resource.health)return resource.health;if(resource.addresses?.length)return resource.addresses.join(' · ');return resource.provenance.sourceId}
function evidenceFor(key:string){const edge=props.graph.relations.find(r=>r.from===key||r.to===key);return edge?.evidence||'observed'}
function nodeClass(resource:SreResource,index:number){const kind=resource.provenance.kind.toLowerCase();return[`node-${index+1}`,{'graph-node--storage':kind.includes('volume'),'graph-node--network':kind.includes('network')||kind.includes('nic')||kind.includes('loadbalancer'),'graph-node--selected':selected.value===resource.key}]}
function line(index:number){const lines=[{x1:190,y1:180,x2:420,y2:140},{x1:190,y1:190,x2:420,y2:360},{x1:510,y1:145,x2:700,y2:145},{x1:510,y1:365,x2:700,y2:330},{x1:790,y1:145,x2:940,y2:120},{x1:790,y1:330,x2:940,y2:350}];return lines[index%lines.length]}
</script>
<style scoped>.evidence-shell{border-radius:8px}.graph-toolbar{min-height:52px;padding:0 14px;font-size:12px}.zoom button{min-width:36px;height:32px;font-size:12px}.graph-canvas{min-height:610px}.lanes{padding:20px;font-size:10px}.graph-node{width:166px;min-height:126px;padding:14px;border-radius:8px}.graph-node strong{margin:13px 0 8px;font-size:14px}.graph-node small,.graph-node em{font-size:10px}.graph-node em{margin-top:10px}.evidence-popover{width:360px;padding:15px;border-radius:8px}.evidence-popover h3{font-size:13px;margin-bottom:10px}.fallback{padding:12px;font-size:12px}</style>
<style scoped>.evidence-shell{border:1px solid var(--ic-border);border-radius:13px;background:var(--ic-surface);overflow:hidden}.graph-toolbar{display:flex;justify-content:space-between;align-items:center;min-height:70px;padding:0 18px;border-bottom:1px solid var(--ic-border);color:var(--ic-text-muted)}.zoom{display:flex}.zoom button{min-width:44px;height:42px;border:1px solid var(--ic-border);background:transparent;color:var(--ic-text);font-size:15px}.zoom button:first-child{border-radius:9px 0 0 9px}.zoom button:last-child{border-radius:0 9px 9px 0}.graph-canvas{position:relative;min-height:690px;overflow:hidden;background-color:#1b202a;background-image:linear-gradient(#303745 1px,transparent 1px),linear-gradient(90deg,#303745 1px,transparent 1px);background-size:52px 52px}.lanes{display:grid;grid-template-columns:repeat(4,1fr);padding:26px;color:var(--ic-text-muted);font-size:11px;font-weight:700;letter-spacing:.06em}.connectors{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.connectors line{stroke:#8290d1;stroke-width:3;opacity:.72}.graph-node{position:absolute;width:190px;min-height:150px;padding:20px;text-align:left;border:1px solid var(--ic-border);border-left:4px solid #9cabff;border-radius:12px;background:#171b23;color:var(--ic-text);box-shadow:0 12px 30px rgba(0,0,0,.18)}.graph-node span{display:block;color:var(--ic-text-muted);font-size:10px;letter-spacing:.11em}.graph-node strong{display:block;margin:20px 0 13px;font-size:18px}.graph-node small{display:block;line-height:1.7}.graph-node em{display:block;margin-top:15px;color:#68a5ff;font-size:11px;font-style:normal}.graph-node--network{border-left-color:#68a5ff}.graph-node--storage{border-left-color:#54dca0}.graph-node--selected{outline:2px solid #68a5ff}.node-1{left:3%;top:180px}.node-2{left:26%;top:100px}.node-3{left:26%;top:380px}.node-4{left:55%;top:100px}.node-5{left:55%;top:380px}.node-6{right:3%;top:80px}.node-7{right:3%;top:380px}.node-8{left:40%;top:520px}.evidence-popover{position:absolute;left:31%;bottom:22px;width:430px;padding:20px;border:1px solid #68a5ff;border-radius:12px;background:#171b23;box-shadow:0 16px 40px rgba(0,0,0,.35)}.evidence-popover h3{font-size:15px;margin:0 0 16px}.evidence-popover span{display:block;color:var(--ic-text-muted);font-size:12px}.evidence-popover code{display:block;width:max-content;max-width:100%;margin:12px 0;padding:4px 9px;border-radius:6px;background:#2a2f39;color:var(--ic-text-muted);overflow:hidden;text-overflow:ellipsis}.evidence-popover p{margin:0;color:var(--ic-text-muted);font-size:12px}.fallback{padding:16px}.fallback summary{cursor:pointer;font-weight:600}@media(max-width:1050px){.graph-canvas{min-height:900px}.lanes{display:none}.graph-node{position:relative;inset:auto!important;display:inline-flex;vertical-align:top;flex-direction:column;margin:16px;width:calc(50% - 36px)}.connectors,.evidence-popover{display:none}}@media(max-width:650px){.graph-node{width:calc(100% - 32px)}.graph-canvas{min-height:auto}}</style>
